import test from 'node:test';
import assert from 'node:assert/strict';
import { Interface, id } from 'ethers';

const signature = 'deposit((address,address,uint24,int24,address),int24,int24,uint128,uint128,uint128,uint256)';
const abi = ['function ' + signature];
const iface = new Interface(abi);

const cases = [
  {
    name: 'CASHCAT/USDG manual range replacement',
    data: '',
    currency0: '0x020bfC650A365f8BB26819deAAbF3E21291018b4',
    currency1: '0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168',
    tickSpacing: 60,
    tickLower: -295080,
    tickUpper: -294840,
    liquidity: 416346248331525075n
  },
  {
    name: 'USDG/ZZZ first deposit',
    data: '',
    currency0: '0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168',
    currency1: '0x7dbf38976f6D3b9c529e7D9484A71898B409eE6a',
    tickSpacing: 200,
    tickLower: 312600,
    tickUpper: 313000,
    liquidity: 603915329638896163n
  },
  {
    name: 'USDG/ZZZ add to same range',
    data: '',
    currency0: '0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168',
    currency1: '0x7dbf38976f6D3b9c529e7D9484A71898B409eE6a',
    tickSpacing: 200,
    tickLower: 312600,
    tickUpper: 313000,
    liquidity: 56128244599284701n
  }
];

test('candidate Fables deposit signature matches observed selector', () => {
  assert.equal(id(signature).slice(0, 10), '0x36a9ca1a');
});

for (const c of cases) {
  test('decode real deposit: ' + c.name, () => {
    const decoded = iface.decodeFunctionData('deposit', c.data);
    const key = decoded[0];
    assert.equal(String(key.currency0).toLowerCase(), c.currency0.toLowerCase());
    assert.equal(String(key.currency1).toLowerCase(), c.currency1.toLowerCase());
    assert.equal(Number(key.fee), 0x800000);
    assert.equal(Number(key.tickSpacing), c.tickSpacing);
    assert.equal(String(key.hooks).toLowerCase(), '0x08e52564bad99e05a694b4809f397edca417a080');
    assert.equal(Number(decoded[1]), c.tickLower);
    assert.equal(Number(decoded[2]), c.tickUpper);
    assert.equal(BigInt(decoded[3]), c.liquidity);
    assert.ok(BigInt(decoded[4]) > 0n);
    assert.ok(BigInt(decoded[5]) > 0n);
    assert.ok(BigInt(decoded[6]) > 0n);
  });
}
